 style=\"background-color: #000; color: #fff; padding: 10px 20px; font-weight: bold; font-size: 20px; border: 2px solid #000;\"><span style=\"margin-right: 20px;\">PART B3 </span>OTHER SERVICE <i>(continued)</i></td>\r\n          </tr>\r\n          <tr>\r\n            <td style=\"border: 2px solid #000; padding: 15px;\">\r\n            <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n              <tbody>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\">\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"height: 30px; width: 30px; min-width: 30px; \"><input name=\"check5\" style=\"margin: 0; vertical-align: top; height: 30px; width: 30px \" type=\"checkbox\" /></td>\r\n                        <td colspan=\"2\" style=\"padding-left: 20px;\">I emailed the copy to the email address that was included in the entity’s address for service.</td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\">\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"width: 55px; min-width: 55px;\">&nbsp;</td>\r\n                        <td colspan=\"3\" style=\"height: 25px; padding:0 15px; width: 100%; border: 2px solid #000;\">&nbsp;</td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\">\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"height: 30px; width: 30px; min-width: 30px; vertical-align: top;\"><input name=\"check5\" style=\"margin: 0; vertical-align: top; height: 30px; width: 30px \" type=\"checkbox\" /></td>\r\n                        <td colspan=\"2\" style=\"padding-left: 20px;\">I electronically transmitted the copy to the non-fax or email electronic address that was included in the entity’s address for service (e.g. via a website)</td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td>\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"width: 55px; min-width: 55px;\">&nbsp;</td>\r\n                        <td colspan=\"3\" style=\"height: 25px; padding:0 15px; width: 100%; border: 2px solid #000;\">&nbsp;</td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\">\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"width: 55px; min-width: 55px;\">&nbsp;</td>\r\n                        <td colspan=\"3\"><i>(insert electronic address)</i></td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td>\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"height: 30px; width: 30px; min-width: 30px; vertical-align: top;\"><input name=\"check7\" style=\"margin: 0; vertical-align: top; height: 30px; width: 30px \" type=\"checkbox\" /></td>\r\n                        <td style=\"padding-left: 20px;\">I left the copy with a person<i> (insert name)</i></td>\r\n                        <td style=\"height: 25px; width: 50%; border: 2px solid #000;\">&nbsp;</td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\">\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"padding: 0; width: 55px; \">&nbsp;</td>\r\n                        <td colspan=\"2\">who is apparently an adult and apparently residing or employed at the entity’s address for service, namely <i>(insert address)</i></td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td>\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"height: 30px; width: 30px; min-width: 30px; vertical-align: top;\"><input name=\"check8\" style=\"margin: 0; vertical-align: top; height: 30px; width: 30px \" type=\"checkbox\" /></td>\r\n                        <td style=\"padding-left: 20px;\">I left the copy with a person<i> (insert name)</i></td>\r\n                        <td style=\"height: 25px; width: 50%; border: 2px solid #000;\">&nbsp;</td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\">\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"padding: 0; width: 55px; \">&nbsp;</td>\r\n                        <td colspan=\"2\">who is apparently an adult and apparently residing or employed at the address in accordance with the service practice direction at which documents may be left with a person in circumstances where the entity does not have an address for service, namely<i>(insert address)</i></td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\">\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"width: 55px; min-width: 55px;\">&nbsp;</td>\r\n                        <td colspan=\"3\" style=\"height: 25px; padding:0 15px; width: 100%; border: 2px solid #000;\">&nbsp;</td>\r\n                      </tr>\r\n                      <tr>\r\n                        <td style=\"width: 55px; min-width: 55px;\">&nbsp;</td>\r\n                        <td style=\"height: 25px; padding:0 15px; width: 100%; border: 2px solid #000;\">&nbsp;</td>\r\n                        <td style=\"padding: 0 20px; font-weight: bold;\">Postcode</td>\r\n                        <td style=\"height: 25px; padding:0 15px; min-width: 100px; width: 100%; border: 2px solid #000;\">&nbsp;</td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td>\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"height: 30px; width: 30px; min-width: 30px; \"><input name=\"check5\" style=\"margin: 0; vertical-align: top; height: 30px; width: 30px \" type=\"checkbox\" /></td>\r\n                        <td colspan=\"2\" style=\"padding-left: 20px;\">I served the copy in another way in accordance with the service practice direction, namely</td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\">\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"width: 55px; min-width: 55px;\">&nbsp;</td>\r\n                        <td style=\"height: 25px; padding:0 15px; width: 100%; border: 2px solid #000;\">&nbsp;</td>\r\n                      </tr>\r\n                      <tr>\r\n                        <td style=\"width: 55px; min-width: 55px;\">&nbsp;</td>\r\n                        <td><i>(insert method of service)</i></td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\">\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"height: 30px; width: 30px; min-width: 30px; vertical-align: top;\"><input name=\"check5\" style=\"margin: 0; vertical-align: top; height: 30px; width: 30px \" type=\"checkbox\" /></td>\r\n                        <td style=\"width: 40%;\">I otherwise served the copy in accordance with an Actnamely by</td>\r\n                        <td style=\"height: 25px; padding:0 15px; width: 50%; border: 2px solid #000;\">&nbsp;</td>\r\n                      </tr>\r\n                      <tr>\r\n                        <td colspan=\"2\" style=\"width: 55px; min-width: 55px;\">&nbsp;</td>\r\n                        <td><i>(nsert name of Act)</i></td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td>\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"min-width: 55px; width: 55px;\">&nbsp;</td>\r\n                        <td style=\"height: 25px; padding:0 15px; width: 100%; border: 2px solid #000;\">&nbsp;</td>\r\n                      </tr>\r\n                      <tr>\r\n                        <td style=\"min-width: 55px; width: 55px;\">&nbsp;</td>\r\n                        <td><i>(insert method of service)</i></td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            </td>\r\n          </tr>\r\n          <tr>\r\n            <td style=\"padding: 20px;\">\r\n            <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n              <tbody>\r\n                <tr>\r\n                  <td style=\"width: 50%; padding: 10px; \"><span style=\"height: 25px; padding:0 10px; border: 2px solid #000; width: 90%; display: block;\">&nbsp;</span></td>\r\n                  <td style=\"width: 50%; padding: 10px; \"><span style=\"height: 25px; padding:0 10px; border: 2px solid #000; width: 90%; display: block;\">&nbsp;</span></td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding: 0 20px;\"><i>Person making affidavit to sign</i></td>\r\n                  <td style=\"padding: 0 20px;\"><i>Person taking the affidavit to sign (qualified witness)</i></td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            </td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n      </td>\r\n    </tr>\r\n    <!-- PART C -->\r\n    <tr>\r\n      <td style=\" padding: 0 0 30px 0;\">\r\n      <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n        <tbody>\r\n          <tr>\r\n            <td style=\"background-color: #000; color: #fff; padding: 10px 20px; font-weight: bold; font-size: 20px; border: 2px solid #000;\"><span style=\"margin-right: 20px;\">PART C </span>DOCUMENT SERVED</td>\r\n          </tr>\r\n          <tr>\r\n            <td style=\"border: 2px solid #000; padding: 15px;\">\r\n            <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n              <tbody>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\">One of the following must apply, please tick as appropriate:</td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\">\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"height: 30px; width: 30px; min-width: 30px; \"><input name=\"check5\" style=\"margin: 0; vertical-align: top; height: 30px; width: 30px \" type=\"checkbox\" /></td>\r\n                        <td colspan=\"2\" style=\"padding-left: 20px;\">I have attached to this affidavit a copy of the document served, or</td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\">\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"height: 30px; width: 30px; min-width: 30px; \"><input name=\"check5\" style=\"margin: 0; vertical-align: top; height: 30px; width: 30px \" type=\"checkbox\" /></td>\r\n                        <td colspan=\"2\" style=\"padding-left: 20px;\">I have already filed the document which is named above in Part B.</td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            </td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n      </td>\r\n    </tr>\r\n    <!-- PART D -->\r\n    <tr>\r\n      <td style=\" padding: 0 0 30px 0;\">\r\n      <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n        <tbody>\r\n          <tr>\r\n            <td style=\"background-color: #000; color: #fff; padding: 10px 20px; font-weight: bold; font-size: 20px; border: 2px solid #000;\"><span style=\"margin-right: 20px;\">PART D </span>INTERSTATE SERVICE</td>\r\n          </tr>\r\n          <tr>\r\n            <td style=\"border: 2px solid #000; padding: 15px;\">\r\n            <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n              <tbody>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\">This part only applies if you served the document interstate. Tick as applicable.</td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\">\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"height: 30px; width: 30px; min-width: 30px; \"><input name=\"check5\" style=\"margin: 0; vertical-align: top; height: 30px; width: 30px \" type=\"checkbox\" /></td>\r\n                        <td colspan=\"2\" style=\"padding-left: 20px;\">I did attach the notice under the <i>Service and Execution of Process Act 1992</i> (Commonwealth) to the document.</td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\">\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"height: 30px; width: 30px; min-width: 30px; \"><input name=\"check5\" style=\"margin: 0; vertical-align: top; height: 30px; width: 30px \" type=\"checkbox\" /></td>\r\n                        <td colspan=\"2\" style=\"padding-left: 20px;\">I did not attach the notice under the <i>Service and Execution of Process Act 1992</i> (Commonwealth) to the document.</td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            </td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n      </td>\r\n    </tr>\r\n    <!-- Warning -->\r\n    <tr>\r\n      <td style=\" padding: 0 0 30px 0;\">\r\n      <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n        <tbody>\r\n          <tr>\r\n            <td style=\"background-color: #000; color: #fff; padding: 10px 20px; font-weight: bold; font-size: 20px; border: 2px solid #000;\"><span style=\"margin-right: 20px;\">Warning </span></td>\r\n          </tr>\r\n          <tr>\r\n            <td style=\"border: 2px solid #000; padding: 15px;\">\r\n            <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n              <tbody>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\">Section 216 of the Queensland Civil and Administrative Tribunal Act 2009 makes it an offence for a person to knowingly give the registry documents containing false or misleading information. Maximum penalty for such an offence – 100 penalty units.</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            </td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n      </td>\r\n    </tr>\r\n    <!-- SIGNATURE -->\r\n    <tr>\r\n      <td style=\" padding: 0 0 30px 0;\">\r\n      <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n        <tbody>\r\n          <tr>\r\n            <td style=\"background-color: #000; color: #fff; padding: 10px 20px; font-weight: bold; font-size: 20px; border: 2px solid #000;\"><span style=\"margin-right: 20px;\">SIGNATURE </span></td>\r\n          </tr>\r\n          <tr>\r\n            <td style=\"border: 2px solid #000; padding: 15px;\">\r\n            <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n              <tbody>\r\n                <tr>\r\n                  <td><b>Sworn</b> (or <b>affirmed</b>) by <i>(insert full name)</i></td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"height: 25px; padding:0 15px; width: 100%; border: 2px solid #000;\">&nbsp;</td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding: 15px 0;\">\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"padding-right: 5px;\">on</td>\r\n                        <td style=\"height: 25px; padding:0 15px; width: 50%; border: 2px solid #000;\">&nbsp;</td>\r\n                        <td style=\"padding-left: 5px;\">at</td>\r\n                        <td style=\"padding-right: 5px;\"><i>(place)</i></td>\r\n                        <td style=\"height: 25px; padding:0 15px; width: 50%; border: 2px solid #000;\">&nbsp;</td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td>in the presence of:</td>\r\n                </tr>\r\n                <tr>\r\n                  <td>\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"width: 50%; padding: 0 10px 0 0;\">&nbsp;</td>\r\n                        <td style=\"width: 50%; padding: 0 0 0 10px;\">&nbsp;</td>\r\n                      </tr>\r\n                      <tr>\r\n                        <td style=\"padding:5px 20px 20px;\"><i>Person making affidavit to sign</i></td>\r\n                        <td style=\"padding: 5px 20px 20px;\"><i>Person taking the affidavit to sign (qualified witness)</i></td>\r\n                      </tr>\r\n                      <tr>\r\n                        <td style=\"width: 50%; padding: 0 10px 0 0;\">&nbsp;</td>\r\n                        <td style=\"width: 50%; padding: 0 0 0 10px;\">&nbsp;</td>\r\n                      </tr>\r\n                      <tr>\r\n                        <td style=\"padding: 0 20px;\">&nbsp;</td>\r\n                        <td style=\"padding: 0 20px;\"><i>Print name</i></td>\r\n                      </tr>\r\n                      <tr>\r\n                        <td style=\"padding: 0 20px;\">&nbsp;</td>\r\n                        <td style=\"padding: 40px 0 0 20px;\"><b>Commissioner for declarations / solicitor / justice of the peace</b></td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            </td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n      </td>\r\n    </tr>\r\n    <!-- Instructions for completing -->\r\n    <tr>\r\n      <td style=\"padding-bottom: 20px;\">\r\n      <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n        <tbody>\r\n          <tr>\r\n            <td style=\"font-size: 20px;\"><b>Instructions for completing</b></td>\r\n          </tr>\r\n          <tr>\r\n            <td>\r\n            <h2>Affidavit of service</h2>\r\n            </td>\r\n          </tr>\r\n          <tr>\r\n            <td style=\"padding: 15px; border: 2px solid #000;\">\r\n            <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n              <tbody>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 15px;\"><b>Use this form where you are seeking, or are required, to prove that you have provided a copy of a document to another party.</b></td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 0;\"><b>Default decisions</b>\r\n                  <p style=\"margin-top: 0;\">Where you are applying for a decision in default of a response by a respondent you will need to prove that you have provided a copy of your application to the respondent. You may complete this affidavit, or in some cases you may complete the affidavit in the application for decision by default (for example the <i> Form 6 – application for decision by default – minor debt)</i>.</p>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 0;\"><b>Interstate service</b>\r\n                  <p style=\"margin-top: 0;\">If the respondent resides in another state or territory you will need to provide an additional notice to the respondent, as required by the Service and Execution of Process Act 1992 (see also Practice Direction 2 of 2014). The notice is available on the QCAT website at www.qcat.qld.gov.au..</p>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-bottom: 0;\"><b>Where to lodge your Affidavit of service</b>\r\n                  <p style=\"margin-top: 0;\">The Affidavit of service must be lodged in the QCAT registry where the application that started the proceeding was lodged.</p>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td>\r\n                  <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n                    <tbody>\r\n                      <tr>\r\n                        <td style=\"width: 100px; vertical-align: top;\"><i>By post:</i></td>\r\n                        <td style=\"padding-bottom: 10px; vertical-align: top;\">\r\n                        <p style=\"margin-top: 0;&gt;QCAT, GPO Box 1639, Brisbane QLD 4001&lt;/p&gt;\r\n                          &lt;p style=\"><i>If you are posting your original response and/or counter-application and copies to QCAT, you need to include a stamped self-addressed A4 envelope with your material.</i></p>\r\n                        </td>\r\n                      </tr>\r\n                      <tr>\r\n                        <td style=\"width: 100px; vertical-align: top;\"><i>In person:</i></td>\r\n                        <td style=\"vertical-align: top;\">\r\n                        <p style=\"margin-top: 0;\">QCAT, Level 9, Bank of Queensland Building, 259 Queen Street, Brisbane QLD 4000, or at any Magistrates Court outside of the Brisbane CBD.</p>\r\n                        </td>\r\n                      </tr>\r\n                    </tbody>\r\n                  </table>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding: 0;\">\r\n                  <p>For more information visit www.qcat.qld.gov.au or call 1300 753 228.</p>\r\n                  </td>\r\n                </tr>\r\n                <tr>\r\n                  <td><b>PART B DETAILS OF SERVICE</b>\r\n                  <p>Refer to the Queensland Civil and Administrative Tribunal Rules 2009 and the tribunal’s practice directions for service requirements available at www.qcat.qld.gov.au.</p>\r\n\r\n                  <p>Insert your full name and residential or business address or place of employment.</p>\r\n\r\n                  <p>If the entity served is not an individual then the correct name must be used. For example, a company name, business name (regardless of whether it is registered) or a State agency name. For further information you can refer to the tribunal’s factsheet How to identify and name parties in QCAT available at www.qcat.qld.gov.au.</p>\r\n\r\n                  <p>If you are serving an application for a minor debt claim you must deliver the copy to an entity personally and in a way that complies with QCAT’s practice direction on service. Practice Directions are available at www.qcat.qld.gov.au.</p>\r\n                  </td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            </td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n      </td>\r\n    </tr>\r\n    <!-- Instructions for completing -->\r\n    <tr>\r\n      <td style=\"padding: 15px; border: 2px solid #000;\">\r\n      <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n        <tbody>\r\n          <tr>\r\n            <td><b>SIGNATURE</b>\r\n            <p>Please sign in the presence of a person who is authorised by the Oaths Act 1867 to take an affidavit:</p>\r\n            </td>\r\n          </tr>\r\n          <tr>\r\n            <td>\r\n            <table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n              <tbody>\r\n                <tr>\r\n                  <td style=\"padding-right: 20px; padding-bottom: 5px; vertical-align: top;\">(a)</td>\r\n                  <td>a justice, commissioner for declarations or notary public under the law of Queensland, the Commonwealth or another State,</td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-right: 20px; padding-bottom: 5px; vertical-align: top;\">(b)</td>\r\n                  <td>a lawyer,</td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-right: 20px; padding-bottom: 5px; vertical-align: top;\">(c)</td>\r\n                  <td>a conveyancer, or another person authorised to administer an oath, under the law of the state, the Commonwealth or another state,</td>\r\n                </tr>\r\n                <tr>\r\n                  <td style=\"padding-right: 20px; padding-bottom: 5px; vertical-align: top;\">(d)</td>\r\n                  <td>if the affidavit is taken outside Australia — a person authorised to administer an oath under the law of the place in which the affidavit is taken.</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n            </td>\r\n          </tr>\r\n          <tr>\r\n            <td><b>Each page must be signed in the presence of a qualified witness.</b>\r\n            <p>A qualified witness includes a lawyer, Justice of the Peace or a Commissioner for Declarations.</p>\r\n            <b>Your Information</b>\r\n\r\n            <p>QCAT collects your contact details for the purposes of compliance with the Queensland Civil and Administrative Tribunal Act 2009 in relation to proceedings in QCAT. QCAT may contact you to seek your assistance in research to assist in the evaluation of the operation of QCAT. You are not obliged to participate in feedback or surveys. If you do participate no identifying particulars will be published. QCAT will not disclose your contact details or any other personal information to a third party unless required by law.</p>\r\n            </td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n      </td>\r\n    </tr>\r\n    <!-- Footer start here -->\r\n    <tr>\r\n      <td style=\"padding-top: 30px;\"><img alt=\"qcatfoot\" data-align=\"center\" data-entity-type=\"file\" data-entity-uuid=\"824474b7-c4f8-41e7-b38f-620e092b6844\" src=\"/sites/default/files/inline-images/qcatfooter.png\" width=\"725\" /></td>\r\n    </tr>\r\n  </tbody>\r\n</table>\r\n','','full_html'),('library',0,268,384,'en',0,'<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#fff;\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"line-height: 1.5;\">\r\n			<table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\" font-size: 14px; line-height: 17px;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td colspan=\"2\">\r\n						<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\r\n							<tbody>\r\n								<tr>\r\n									<td>\r\n									<p style=\"margin: 0; font-weight: bold; font-size: 24px;  text-align: center; padding: 15px 10px 15px;\">AFFIDAVIT OF SERVICE BY HAND (DIVORCE)</p>\r\n									</td>\r\n								</tr>\r\n								<tr>\r\n									<td>\r\n									<table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\r\n										<tbody>\r\n											<tr>\r\n												<td colspan=\"2\" style=\"padding-bottom: 10px;\">\r\n												<table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\r\n													<tbody>\r\n														<tr>\r\n															<td style=\"font-size: 14px;  width: 50%;\">\r\n															<p style=\"margin: 0; padding-bottom: 8px;\">Filed in:</p>\r\n\r\n															<p style=\"margin: 0; \"><input checked=\"checked\" style=\" padding-right: 5px;\" type=\"checkbox\" /><span style=\"padding-left: 4px; vertical-align: top;\">Federal Circuit Court of Australia</span></p>\r\n\r\n															<p style=\"margin: 0; \"><input style=\"padding-right: 5px;\" type=\"checkbox\" /><span style=\"padding-left: 4px; vertical-align: top;\">Family Court of Australia</span></p>\r\n\r\n															<p style=\"margin: 0; \"><input style=\" padding-right: 5px;\" type=\"checkbox\" /><span style=\"padding-left: 4px; vertical-align: top;\">Filed Family Court of Western Australia</span></p>\r\n\r\n															<p style=\"margin: 0; \"><input style=\"vertical-align: middle; padding-right: 5px;\" type=\"checkbox\" /><span style=\"padding-left: 4px; vertical-align: top;\">Other (specify):</span></p>\r\n\r\n															<p style=\"font-weight: bold; margin: 0; line-height: 22px;padding-top: 6px;\">The applicant cannot serve the respondent.</p>\r\n\r\n															<p style=\"margin: 0;\">If the respondent signed the Acknowledgment of Service (Divorce), it must be attached to this form.</p>\r\n\r\n															<p>&nbsp;</p>\r\n															</td>\r\n															<td style=\"vertical-align: top;  width: 50%; line-height: 1.8;  border: 1px solid #000;\">\r\n															<p style=\"margin: 0; padding-left: 10px;\"><span style=\"padding-right: 6px;\">Client ID:</span></p>\r\n\r\n															<p style=\"margin: 0; padding-left: 10px;  border-bottom: 1px solid #000;\"><span style=\"padding-right: 6px;\">File number </span><span style=\" \">[node:field_case_no]</span></p>\r\n\r\n															<p style=\"margin: 0; text-align: right; padding-right: 20px;\">COURT USE ONLY</p>\r\n\r\n															<p style=\"margin: 0; text-align: left; padding-left: 10px;\">Filed at</p>\r\n\r\n															<p style=\"margin: 0; text-align: left;padding-left: 10px;\">Filed on</p>\r\n\r\n															<p style=\"margin: 0; text-align: left;padding-left: 10px;\">Court location</p>\r\n\r\n															<p style=\"margin: 0; text-align: left;padding-left: 10px;\">Court date</p>\r\n\r\n															<p style=\"margin: 0; text-align: left;  padding-left: 10px; padding-bottom: 15px;\">Court time</p>\r\n															</td>\r\n														</tr>\r\n													</tbody>\r\n												</table>\r\n												</td>\r\n											</tr>\r\n											<tr>\r\n												<td style=\"width: 180px; vertical-align: top; padding-top: 6px; padding-bottom: 8px;font-size: 20px; line-height: 25px; font-weight: bold;\">Part A</td>\r\n												<td style=\"font-size: 20px; line-height: 25px; padding-bottom: 8px;  padding-top: 6px; font-weight: bold;\">Person serving documents</td>\r\n											</tr>\r\n											<tr>\r\n												<td colspan=\"1\" style=\"width: 180px; vertical-align: top;  font-weight: bold; padding: 2px 6px;\"><span style=\"padding-right: 6px;\">1. </span>Name</td>\r\n												<td colspan=\"1\" style=\"border: 1px solid #000; border-bottom: none; padding: 2px 6px;\">\r\n												<p style=\"margin: 0;\"><span style=\"padding-right: 8px;\">Family name</span> <span style=\"padding-left: 10px;\">[node:field_allocated_to]</span></p>\r\n\r\n												<p style=\"margin: 0;\"><span style=\"padding-right: 8px;\">Given names</span><span style=\"padding-left: 10px;\">[node:field_allocated_to]</span></p>\r\n												</td>\r\n											</tr>\r\n											<tr>\r\n												<td colspan=\"1\" style=\"width: 180px; vertical-align: top;  font-weight: bold; padding: 2px 6px;\"><span style=\"padding-right: 6px;\">2. </span>Address</td>\r\n												<td colspan=\"1\" style=\"border: 1px solid #000; border-bottom: none; padding: 2px 6px;\">\r\n												<p style=\"margin: 0;\"><span style=\"\">Level 25, Aurora Place, 88 Phillip Street, Sydney</span></p>\r\n												<span style=\"margin: 0; padding-right: 30%;\">State <span style=\"\">NSW</span></span> <span style=\"margin: 0; padding-left: 40%;\">Postcode <span style=\"\">2000</span></span></td>\r\n											</tr>\r\n											<tr>\r\n												<td colspan=\"1\" style=\"width: 180px; vertical-align: top;  font-weight: bold; padding: 2px 6px;\"><span style=\"padding-right: 6px;\">3. </span>Occupation</td>\r\n												<td colspan=\"1\" style=\"border: 1px solid #000;  padding: 2px 6px;\">\r\n												<p style=\"margin: 0;\"><span style=\"\">Licensed Process Server</span></p>\r\n												</td>\r\n											</tr>\r\n											<tr>\r\n												<td style=\"width: 180px; vertical-align: top; padding-top: 6px; padding-bottom: 8px;font-size: 20px; line-height: 25px; font-weight: bold;\">Part B</td>\r\n												<td style=\"font-size: 20px; line-height: 25px; padding-bottom: 8px;  padding-top: 6px; font-weight: bold;\">Details of service</td>\r\n											</tr>\r\n											<tr>\r\n												<td colspan=\"1\" style=\"width: 180px; vertical-align: top;  font-weight: bold; padding: 2px 6px;\"><span style=\"padding-right: 6px;\">4. </span>Person served (respondent)</td>\r\n												<td colspan=\"1\" style=\"border: 1px solid #000; border-bottom: none; padding: 2px 6px;\">\r\n												<p style=\"margin: 0;\"><span style=\"padding-right: 5px;\">Family name</span><span style=\"padding-left: 10px;\">Maginn</span></p>\r\n\r\n												<p style=\"margin: 0;\"><span style=\"padding-right: 5px;\">Given names</span><span style=\"padding-left: 10px;\">Kate Maree</span></p>\r\n												</td>\r\n											</tr>\r\n											<tr>\r\n												<td colspan=\"1\" style=\"width: 180px; vertical-align: top;  font-weight: bold; padding: 2px 6px;\"><span style=\"padding-right: 6px;\">5. </span>Date documents served</td>\r\n												<td colspan=\"1\" style=\"border: 1px solid #000; border-bottom: none; padding: 2px 6px 13px 6px;\">\r\n												<p style=\"margin: 0;\"><span style=\"\">28</span>/<span style=\"\">03</span>/<span style=\"\">2020</span></p>\r\n												</td>\r\n											</tr>\r\n											<tr>\r\n												<td colspan=\"1\" style=\"width: 180px; vertical-align: top;  font-weight: bold; padding: 2px 6px;\"><span style=\"padding-right: 6px;\">6. </span>What documents were served?</td>\r\n												<td colspan=\"1\" style=\"border: 1px solid #000; border-bottom: none; padding: 2px 6px;\">\r\n												<p style=\"margin: 0; vertical-align: middle;\"><span style=\"padding-right: 6px; vertical-align: middle;\"><input checked=\"checked\" style=\"padding-right: 6px; vertical-align: middle;\" type=\"checkbox\" /></span><span style=\"vertical-align: top;\">Application for Divorce</span></p>\r\n\r\n												<p style=\"margin: 0; vertical-align: middle;\"><span style=\"padding-right: 6px; vertical-align: middle;\"><input checked=\"checked\" style=\"padding-right: 6px; vertical-align: middle;\" type=\"checkbox\" /></span> <span style=\"vertical-align: top;\">Marriage, Families &amp; Separation brochure</span></p>\r\n\r\n												<p style=\"margin: 0;\"><span style=\"padding-right: 6px; vertical-align: middle;\"><input checked=\"checked\" style=\"padding-right: 6px;\" type=\"checkbox\" /></span> <span style=\"padding-right: 6px; vertical-align: top;\">Other (give details):</span></p>\r\n												</td>\r\n											</tr>\r\n											<tr>\r\n												<td colspan=\"1\" style=\"width: 180px; vertical-align: top;  font-weight: bold; padding: 6px;\"><span style=\"padding-right: 6px;\">7. </span>What documents were served?</td>\r\n												<td colspan=\"1\" style=\"border: 1px solid #000;  padding: 2px 6px;\">\r\n												<p style=\"margin: 0;\"><span style=\"padding-right: 6px; vertical-align: middle;\"><input checked=\"checked\" style=\"padding-right: 6px; vertical-align: middle;\" type=\"checkbox\" /></span> <span style=\"padding-right: 6px; vertical-align: middle;\">I handed them to the person at (give address):</span><span style=\" padding: 0 5px; vertical-align: top;\">[node:field_service_address]</span></p>\r\n\r\n												<p style=\"margin: 0; padding-bottom: 15px;\"><span style=\"padding-right: 6px; vertical-align: middle;\"><input style=\"padding-right: 6px; vertical-align: middle;\" type=\"checkbox\" /></span> <span style=\"padding-right: 6px; vertical-align: middle;\">I attempted to hand them to the person at (give address):</span></p>\r\n\r\n												<p style=\"margin: 0;\"><span style=\"padding-right: 6px; vertical-align: middle;\"><input style=\"padding-right: 6px; vertical-align: middle;\" type=\"checkbox\" /></span> <span style=\"padding-right: 6px; vertical-align: middle;\">The person refused to accept them. I put them down and left them<br />\r\n												in the presence of the person and told the person what they were.</span></p>\r\n												</td>\r\n											</tr>\r\n											<tr>\r\n												<td style=\"width: 180px; vertical-align: top; padding-top: 6px; padding-bottom: 8px;font-size: 20px; line-height: 25px; font-weight: bold;\">Part C</td>\r\n												<td style=\"font-size: 20px; line-height: 25px; padding-bottom: 8px;  padding-top: 6px; font-weight: bold;\">Identity of person served</td>\r\n											</tr>\r\n											<tr>\r\n												<td colspan=\"1\" style=\"width: 180px; vertical-align: top;  font-weight: bold; padding: 6px;\"><span style=\"padding-right: 6px;\">8. </span>What documents were served?</td>\r\n												<td colspan=\"1\" style=\"border: 1px solid #000;  padding: 2px 6px;\">\r\n												<p style=\"margin: 0;\"><span style=\"padding-right: 6px; vertical-align: middle;\"><input style=\" padding-right: 6px; vertical-align: middle;\" type=\"checkbox\" /></span> <span style=\"padding-right: 6px; vertical-align: middle; padding-top: 6px;\">I know the person</span></p>\r\n\r\n												<p style=\"margin: 0;\"><span style=\"padding-right: 6px; vertical-align: middle;\"><input style=\"padding-right: 6px;\" type=\"checkbox\" /></span> <span style=\"padding-right: 6px; vertical-align: middle;\">The person is shown in the attached photograph</span></p>\r\n\r\n												<p style=\"margin: 0;\"><span style=\"padding-right: 6px; vertical-align: middle;\"><input checked=\"checked\" style=\"padding-right: 6px;\" type=\"checkbox\" /></span> <span style=\"padding-right: 6px; vertical-align: middle;\">I saw the person sign the attached Acknowledgment of Service (Divorce)</span></p>\r\n\r\n												<p style=\"margin: 0; padding-bottom: 30px;\"><span style=\"padding-right: 6px; vertical-align: middle;\"><input checked=\"checked\" style=\" padding-right: 6px;\" type=\"checkbox\" /></span> <span style=\"padding-right: 6px; vertical-align: middle;\">I spoke to the person at the time of service (give details of conversation relating to identity):</span><br />\r\n												<span style=\" padding: 0 5px; padding-bottom: 6px;\">I said to the person served&nbsp;\"Are you [node:field_name_to_server_value], the Respondent shown here?\" and the person&nbsp;replied \"Yes I am.\"</span></p>\r\n												</td>\r\n											</tr>\r\n										</tbody>\r\n									</table>\r\n									</td>\r\n								</tr>\r\n							</tbody>\r\n						</table>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n			<table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse; border-spacing: 0; width:100%;\" width=\"100% \">\r\n				<tbody>\r\n					<tr>\r\n						<td colspan=\"2\" style=\"width: 100%;\">\r\n						<table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse; border-spacing: 0; width:100%; padding-bottom: 30px;\" width=\"100%\">\r\n							<tbody>\r\n								<tr>\r\n									<td style=\"width: 180px; vertical-align: top; padding-top: 6px; padding-bottom: 8px;font-size: 25px; line-height: 40px; font-weight: bold;\">Part D</td>\r\n									<td style=\"font-size: 25px; line-height: 40px; padding-bottom: 8px;  padding-top: 6px; font-weight: bold;\">Signing</td>\r\n								</tr>\r\n								<tr>\r\n									<td colspan=\"2\">\r\n									<p style=\"margin: 0; font-weight: bold; padding-bottom: 6px;\">Do not swear/affirm this affidavit until you are with a person who is authorised to witness your signature.</p>\r\n\r\n									<p style=\"margin: 0; vertical-align: middle; \"><span style=\"padding-right: 5px; vertical-align: middle;\">I</span> <input checked=\"checked\" style=\" vertical-align: middle;\" type=\"checkbox\" /> <span style=\"vertical-align: middle;\">swear / <input style=\"padding-right: 4px; vertical-align: middle;\" type=\"checkbox\" /></span><span style=\"vertical-align: middle;\">affirm that:</span></p>\r\n\r\n									<p style=\"margin: 0; \"><span style=\"padding-right: 4px;\">1.</span> I am the server.</p>\r\n\r\n									<p style=\"margin: 0; \"><span style=\"padding-right: 4px;\">2.</span> The facts set out are true.</p>\r\n									</td>\r\n								</tr>\r\n							</tbody>\r\n						</table>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"2\">\r\n			<table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"border-collapse: collapse; border-spacing: 0; width:100%;\" width=\"100%\">\r\n				<tbody>\r\n					<tr>\r\n						<td style=\"width: 50%; border: 1px solid #000; padding-top: 30px;\r\n                        padding-left: 20px;\">Signature</td>\r\n						<td style=\"width: 20px; padding: 10px;\">&nbsp;</td>\r\n						<td style=\"width: 50%; padding: 5px 20px;\">\r\n						<p style=\"margin: 0;\"><span style=\"padding-right: 10px;\">Place</span><span style=\"padding-left: 10px;\">Belrose NSW</span></p>\r\n						<span style=\"margin: 0;\"><span style=\"padding-right: 30px;\">Date</span><span style=\"\"><span style=\"margin: 0;\">/<span style=\"padding: 0 30px;\">/</span> </span></span></span></td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"width: 50%;  padding-top: 30px;\r\n                        padding-left: 20px;\">&nbsp;</td>\r\n						<td style=\"width: 20px; padding: 10px;\">&nbsp;</td>\r\n						<td style=\"width: 50%; padding: 5px 20px;\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"width: 50%; border: 1px solid #000; padding-top: 30px;\r\n                        padding-left: 20px;\">Before me (signature of witness)</td>\r\n						<td style=\"width: 20px; padding: 10px;  \">&nbsp;</td>\r\n						<td style=\"width: 50%; padding: 5px 20px; vertical-align: bottom;\">\r\n						<p style=\"margin: 0; vertical-align: bottom;\">Full name of witness (print name)</p>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"padding: 10px;\">&nbsp;</td>\r\n					</tr>\r\n					<tr>\r\n						<td colspan=\"3\" style=\"padding: 10px; line-height: 22px;\">\r\n						<p style=\"margin: 0;\"><span style=\"padding-right: 6px; vertical-align: middle;\"><input style=\"padding-right: 4px; vertical-align: middle;\" type=\"checkbox\" /></span><span style=\"vertical-align: middle;\"> Lawyer</span></p>\r\n\r\n						<p style=\"margin: 0;\"><span style=\"padding-right: 6px; vertical-align: middle;\"><input checked=\"checked\" style=\"padding-right: 6px; vertical-align: middle;\" type=\"checkbox\" /></span><span style=\"vertical-align: middle;\"> Justice of the Peace</span></p>\r\n\r\n						<p style=\"margin: 0;\"><span style=\"padding-right: 6px; vertical-align: middle;\"><input style=\"padding-right: 6px; vertical-align: middle;\" type=\"checkbox\" /></span> <span style=\"padding-right: 6px;\">Other (specify):</span></p>\r\n\r\n						<p style=\"margin: 0;\"><span style=\"padding-right: 6px; vertical-align: middle;\"><input style=\"padding-right: 6px; vertical-align: middle;\" type=\"checkbox\" /></span> <span style=\"vertical-align: middle;\">Authorised Staff Member of the Court</span></p>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td colspan=\"3\" style=\"font-weight: bold; padding-bottom: 30px;\">The witness must also sign the annexure note on the Acknowledgment of Service (Divorce).</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n','','full_html'),('library',0,269,385,'en',0,'<table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width: 700px; background:#fff; font-family: arial; margin: 0 auto; font-size: 16px; border-collapse: collapse; border-spacing: 0; width:100%;\" w