INSERT INTO `node__field_client_update` VALUES ('client_update',0,313,568,'en',0,'<p>In respect of the attempted personal service of Ms Haque, please make a third and final attempt to serve her at the Ingleburn address (however based on previous attempts it does not appear that she currently&nbsp;resides at same).</p>\r\n\r\n<p>If unsuccessful, please affix the correspondence to the door or leave in the letter box.</p>\r\n','','full_html'),('client_update',0,315,570,'en',0,'<p>Please make a&nbsp;final attempt to serve and if&nbsp;unsuccessful, please affix the correspondence to the door or leave in the letter box.</p>\r\n','','full_html'),('client_update',0,316,571,'en',0,'<p>Please make a&nbsp;final attempt to serve and if&nbsp;unsuccessful, please affix the correspondence to the door or leave in the letter box.</p>\r\n','','full_html'),('client_update',0,317,572,'en',0,'<p>Use Affidavit and not Stat Dec</p>\r\n','','full_html'),('client_update',0,343,598,'en',0,'<p>Please provide an update of attempts ofservice</p>\r\n',NULL,'full_html'),('client_update',0,344,599,'en',0,'<p>Please provide an update of attempts of service</p>\r\n',NULL,'full_html'),('client_update',0,345,600,'en',0,'<p>Please provide an update of attempts of service</p>\r\n',NULL,'full_html'),('client_update',0,362,618,'en',0,'<p>Test update&nbsp;</p>\r\n',NULL,'full_html');
