INSERT INTO `node_revision__body` VALUES ('basic_page',0,3,3,'en',0,'<img alt=\"logo\" data-align=\"center\" data-entity-type=\"file\" data-entity-uuid=\"acaf5efc-56a8-4b60-b7dc-a2ba4b9199f6\" src=\"/sites/default/files/inline-images/Logo.png\" />\r\n<p>&nbsp;</p>\r\n','','full_html'),('library',0,261,337,'en',0,'<p class=\"western\" lang=\"en-AU\"><span style=\"line-height:100%\"><span style=\"font-size:9pt\">Form 41 (version 2)<br />\r\nUCPR </span><span style=\"font-size:9pt\">35.8</span></span></p>\r\n\r\n<h1 class=\"western\" lang=\"en-AU\" style=\"text-align:center\">AFFIDAVIT OF SERVICE OF&nbsp;<font color=\"#0000ff\">[node:field_served_by]</font></h1>\r\n\r\n<h1 class=\"western\" lang=\"en-AU\" style=\"text-align:center\">&nbsp;</h1>\r\n\r\n<table style=\"border-collapse:collapse; width:1157px\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td bgcolor=\"#d9d9d9\" colspan=\"2\" style=\"border-bottom:none; padding:0cm; background-color:#d9d9d9; width:605px; border-top:none; border-right:none; border-left:none\" valign=\"top\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:8px\"><span style=\"page-break-after:avoid\"><b>COURT DETAILS</b></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:349px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">Court</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:805px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">[node:field_court]</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:349px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">Division</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:805px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">[node:field_division]</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:349px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">List</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:805px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">[node:field_list]</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:349px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">Registry</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:805px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">[node:field_registry]</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:349px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">Case number</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:805px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">[node:field_case_no]</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td bgcolor=\"#d9d9d9\" colspan=\"2\" style=\"border-bottom:none; padding:0cm; background-color:#d9d9d9; width:605px; border-top:none; border-right:none; border-left:none\" valign=\"top\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:8px\"><span style=\"page-break-after:avoid\"><b>TITLE OF PROCEEDINGS</b></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:349px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">[First] plaintiff</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:805px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><b>[node:field_parties:field_name] </b></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:349px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">Second plaintiff</p>\r\n\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">Number of plaintiffs</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:805px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">&nbsp;</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:349px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\">&nbsp;</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:805px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\">&nbsp;</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:349px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">[First] defendant</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:805px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><b>[node:field_party_2:field_name]</b></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:349px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">Second defendant</p>\r\n\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">Number of defendants</p>\r\n\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">&nbsp;</p>\r\n\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">&nbsp;</p>\r\n\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">&nbsp;</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:805px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">&nbsp;</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td bgcolor=\"#d9d9d9\" colspan=\"2\" style=\"border-bottom:none; padding:0cm; background-color:#d9d9d9; width:605px; border-top:none; border-right:none; border-left:none\" valign=\"top\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:8px\"><span style=\"page-break-after:avoid\"><b>FILING DETAILS</b></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:349px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">Filed for</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:805px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">[node:field_parties:field_name],&nbsp;[node:field_parties:field_party_type]</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:349px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">&nbsp;</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:349px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">Legal representative</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:805px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">[node:field_client]</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:349px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">Legal representative reference</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:805px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">[node:field_client_ref]</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:349px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">Contact name and telephone</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:805px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">[node:field_client], [node:field_client:field_client_address],&nbsp;[node:field_client:field_telephone]</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px; margin-bottom:5px; text-align:center\"><span style=\"line-height:150%\"><span style=\"page-break-before:always\"><span style=\"font-size:9pt\">[on separate page]</span></span></span></p>\r\n\r\n<table style=\"border-collapse:collapse\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td bgcolor=\"#d9d9d9\" colspan=\"2\" style=\"border-bottom:none; padding:0cm; background-color:#d9d9d9; width:100%; border-top:none; border-right:none; border-left:none\" valign=\"top\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:8px\"><span style=\"page-break-after:avoid\"><b>AFFIDAVIT</b></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:97px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">Name</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:494px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><font color=\"#0000ff\">[node:field_served_by]</font></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:97px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">Address</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:494px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><font color=\"#0000ff\">Level 25, 88 Phillip Street, Sydney NSW 2000</font></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:97px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">Occupation</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:494px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><font color=\"#0000ff\">Licensed Process Server</font></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:97px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">Date</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:494px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\">&nbsp;</p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p class=\"western\" lang=\"en-AU\" style=\"margin-top:8px; margin-bottom:8px\"><span style=\"line-height:150%\">I say on oath: <font color=\"#0000ff\">.</font></span></p>\r\n\r\n<ol>\r\n	<li>\r\n	<p lang=\"en-AU\" style=\"margin-top:8px; margin-bottom:8px\"><span style=\"line-height:150%\">I am a Process Server.</span></p>\r\n	</li>\r\n</ol>\r\n\r\n<ol start=\"2\">\r\n	<li>\r\n	<p lang=\"en-AU\" style=\"margin-top:8px; margin-bottom:8px\"><span style=\"line-height:150%\">I am over the age of 16 years.</span></p>\r\n	</li>\r\n	<li>\r\n	<p lang=\"en-AU\" style=\"margin-top:8px; margin-bottom:8px\"><span style=\"line-height:150%\">On [node:field_date_service] <span style=\"font-size:10pt\">at </span>[node:field_para_address], I served [node:field_name_to_server_value] with the following documents:</span><span style=\"line-height:150%\">(a)&nbsp;[node:field_documents:field_untitled]</span></p>\r\n	</li>\r\n	<li>\r\n	<p lang=\"en-AU\" style=\"margin-top:8px; margin-bottom:8px\"><span style=\"line-height:150%\">I served the documents by [node:field_method_of_service]. </span></p>\r\n	</li>\r\n</ol>\r\n\r\n<ol start=\"5\">\r\n	<li>\r\n	<p lang=\"en-AU\" style=\"margin-top:8px; margin-bottom:8px\"><span style=\"line-height:150%\"><span style=\"page-break-after:avoid\">#At the time of service [name of person served] stated [record what, if anything, the person served said]. <font color=\"#0000ff\">Delete</font> <font color=\"#0000ff\">if nothing was said at time of service or if posted</font></span></span></p>\r\n	</li>\r\n</ol>\r\n\r\n<p lang=\"en-AU\" style=\"margin-left:62px; margin-top:8px; margin-bottom:8px\"><span style=\"line-height:150%\"><span style=\"page-break-after:avoid\"><font color=\"#0000ff\">If you have served the defendant by leaving documents with someone at their home, workplace or place of business, make sure that you explain how you knew that they worked or lived at that address</font><font color=\"#0000ff\">.</font></span></span></p>\r\n\r\n<table style=\"border-collapse:collapse\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:177px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px; margin-bottom:5px\"><span style=\"page-break-after:avoid\">#SWORN #AFFIRMED at</span></p>\r\n\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><span style=\"page-break-after:avoid\"><font color=\"#0000ff\">Delete ‘sworn’ or ‘affirmed’ whichever does not apply</font></span></p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:418px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><span style=\"page-break-after:avoid\"><font color=\"#0000ff\">Town/suburb where affidavit signed</font></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:177px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px; margin-bottom:5px\"><span style=\"page-break-after:avoid\">Signature of deponent</span></p>\r\n\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><span style=\"page-break-after:avoid\"><font color=\"#0000ff\">Deponent is person who signs an affidavit</font></span></p>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid #000000; padding:0cm; width:418px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><span style=\"page-break-after:avoid\"><font color=\"#0000ff\">Deponent should sign here</font></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:177px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><span style=\"page-break-after:avoid\">Name of witness</span></p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:418px; border-top:1px solid #000000; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><span style=\"page-break-after:avoid\"><font color=\"#0000ff\">Name of witness</font></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:177px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><span style=\"page-break-after:avoid\">Address of witness</span></p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:418px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><span style=\"page-break-after:avoid\"><font color=\"#0000ff\">Address of witness</font></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:177px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><span style=\"page-break-after:avoid\">Capacity of witness</span></p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:418px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><span style=\"page-break-after:avoid\">[#Justice of the peace #Solicitor #Barrister #Commissioner for affidavits #Notary public] <font color=\"#0000ff\">Delete whichever does not apply</font></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td colspan=\"2\" style=\"border-bottom:none; padding:0cm; width:610px; border-top:none; border-right:none; border-left:none\" valign=\"top\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px; margin-bottom:5px\"><span style=\"page-break-after:avoid\"><font color=\"#0000ff\">Your witness will need to fill out these details and should know what to include</font></span></p>\r\n\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px; margin-bottom:5px\"><span style=\"page-break-after:avoid\"><span style=\"font-size:9pt\">And as a witness, I certify the following matters concerning the person who made this affidavit (the </span><span style=\"font-size:9pt\"><b>deponent</b></span><span style=\"font-size:9pt\">): </span></span></p>\r\n\r\n			<ol>\r\n				<li value=\"1\">\r\n				<p lang=\"en-AU\" style=\"margin-top:8px\"><span style=\"font-size:9pt\">#</span><span style=\"font-size:9pt\">I saw the face of the deponent. </span><font color=\"#808080\"><span style=\"font-size:9pt\">[OR, delete whichever option is inapplicable]</span></font></p>\r\n				</li>\r\n			</ol>\r\n\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-left:62px; text-indent:-1.63cm; margin-top:5px; margin-bottom:5px\"><span style=\"page-break-after:avoid\"><span style=\"font-size:9pt\">#I did not see the face of the deponent because the deponent was wearing a face covering, but I am satisfied that the deponent had a special justification for not removing the covering.<a class=\"sdfootnoteanc\" href=\"#sdfootnote1sym\" name=\"sdfootnote1anc\"><sup>1</sup></a></span></span></p>\r\n\r\n			<ol start=\"2\">\r\n				<li>\r\n				<p lang=\"en-AU\" style=\"margin-top:8px\"><span style=\"font-size:9pt\">#I have </span><span style=\"font-size:9pt\">known</span><span style=\"font-size:9pt\"> the deponent for at least 12 months. </span><font color=\"#808080\"><span style=\"font-size:9pt\">[OR, delete whichever option is inapplicable]</span></font></p>\r\n				</li>\r\n			</ol>\r\n\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-left:62px; text-indent:-1.63cm; margin-top:5px\"><span style=\"page-break-after:avoid\"><span style=\"font-size:9pt\">#I have confirmed the deponen</span><span style=\"font-size:9pt\">t’s identity using the following identification document:</span></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:177px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-left:62px; text-indent:-1.63cm; margin-top:5px\">&nbsp;</p>\r\n			</td>\r\n			<td style=\"border-bottom:none; padding:0cm; width:418px; border-top:1px solid #000000; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><span style=\"page-break-after:avoid\"><span style=\"font-size:9pt\">Identification document relied on (may be original or certified copy)</span></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:none; padding:0cm; width:177px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><span style=\"page-break-after:avoid\">Signature of witness</span></p>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid #000000; padding:0cm; width:418px; border-top:none; border-right:none; border-left:none\">\r\n			<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px\"><span style=\"page-break-after:avoid\"><font color=\"#0000ff\">Signature of person signing affidavit must be witnessed by a Solicitor, Barrister, Justice of the Peace, Notary Public</font></span></p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px; margin-bottom:5px\"><span style=\"line-height:150%\"><span style=\"font-size:9pt\">Note: The deponent and witness must sign each page of the affidavit. See UCPR 35.7B.</span></span></p>\r\n\r\n<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px; margin-bottom:5px\"><br />\r\n&nbsp;</p>\r\n\r\n<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px; margin-bottom:5px\">&nbsp;</p>\r\n\r\n<p class=\"western\" lang=\"en-AU\" style=\"margin-top:5px; margin-bottom:5px\">&nbsp;</p>\r\n\r\n<div id=\"sdfootnote1\">\r\n<p class=\"sdfootnote-western\" lang=\"en-AU\"><span style=\"line-height:100%\"><a class=\"sdfootnotesym\" href=\"#sdfootnote1anc\" name=\"sdfootnote1sym\">1</a><span style=\"font-size:9pt\">[</span><span style=\"font-size:9pt\"> The only \"special justification\" for not removing a face covering is a legitimate medical reason (at April 2012).]</span></span></p>\r\n</div>\r\n\r\n<div id=\"sdfootnote2\">\r\n<p class=\"sdfootnote-western\" lang=\"en-AU\" style=\"margin-top:5px\"><span style=\"line-height:100%\"><a class=\"sdfootnotesym\" href=\"#sdfootnote2anc\" name=\"sdfootnote2sym\">2</a><span style=\"font-size:9pt\">[</span><sup></sup><span style=\"font-size:9pt\"> \"Identification documents\" include current driver licence, proof of age card, Medicare card, credit card, Centrelink pension card, Veterans Affairs entitlement card, student identity card, citizenship certificate, birth certificate, passport or see </span><font color=\"#0000ff\"><u><a href=\"http://www.legislation.nsw.gov.au/viewtop/inforce/subordleg+697+2011+cd+0+N\"><span style=\"font-size:9pt\">Oaths Regulation 2011</span></a></u></font><span style=\"font-size:9pt\">.]</span></span></p>\r\n</div>\r\n','','full_html'),('library',0,261,351,'en',0,'<table style=\"width: 100%; max-width: 700px; margin: 0 auto;  border-collapse: collapse; border-spacing: 0; font-family: arial;\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%; padding-top: 15px;\">\r\n				<tbody>\r\n					<tr>\r\n						<td style=\"padding: 0 10px;\">\r\n						<table style=\"width: 100%; border-collapse: collapse; border-spacing: 0;\">\r\n							<tbody>\r\n								<tr>\r\n									<td style=\" width: 50%; padding-left: 5px;\">Form 41 (Version 2)<br />\r\n									UCPR 35.8</td>\r\n									<td style=\" \">&nbsp;</td>\r\n								</tr>\r\n							</tbody>\r\n						</table>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td>\r\n						<table style=\"width: 100% ;border-collapse: collapse; border-spacing: 0;\">\r\n							<tbody>\r\n								<tr>\r\n									<td style=\"border-collapse: collapse; border-spacing: 0; padding:10px;\">\r\n									<p style=\"font-weight: bold;margin-bottom: 0;text-align: center;\">AFFIDAVIT OF SERVICE OF DOUGLAS O’CONNOR SWORN 29 September 2017</p>\r\n									</td>\r\n								</tr>\r\n							</tbody>\r\n						</table>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"padding: 0 10px;\">\r\n						<table style=\"width: 100% ;border-collapse: collapse; border-spacing: 0;background-color: #C0C0C0;\">\r\n							<tbody>\r\n								<tr>\r\n									<td>\r\n									<p style=\" font-weight: bold;margin-bottom: 0;padding: 10px 8px 8px; margin: 0;\">COURT DETAILS</p>\r\n									</td>\r\n								</tr>\r\n							</tbody>\r\n						</table>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"padding: 10px;\">\r\n						<table style=\"width: 100%; border-collapse: collapse; border-spacing: 0;\">\r\n							<tbody>\r\n								<tr>\r\n									<td style=\" width: 40%; padding-left: 5px; padding-top: 10px;\">Court</td>\r\n									<td style=\" width: 60%; padding-left: 5px;padding-top: 10px;\">[node:field_court]</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\" width: 40%; padding-left: 5px; padding-top: 10px;\">Division</td>\r\n									<td style=\" width: 60%; padding-left: 5px;padding-top: 10px;\">[node:field_division]</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\" width: 40%; padding-left: 5px; padding-top: 10px;\">List</td>\r\n									<td style=\" width: 60%; padding-left: 5px;padding-top: 10px;\">[node:field_list]</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\" width: 40%; padding-left: 5px; padding-top: 10px;\">Registry</td>\r\n									<td style=\" width: 60%; padding-left: 5px;padding-top: 10px;\">[node:field_registry]</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\" width: 40%; padding-left: 5px; padding-top: 10px; padding-bottom: 10px;\">Case number</td>\r\n									<td style=\" width: 60%; padding-left: 5px;padding-top: 10px; padding-bottom: 10px;\">[node:field_case_no]</td>\r\n								</tr>\r\n							</tbody>\r\n						</table>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						