;\">\r\n										<tbody>\r\n											<tr>\r\n												<td style=\"height: 30px; width: 30px; min-width: 30px; \"><input name=\"check5\" style=\"margin: 0; vertical-align: top; height: 30px; width: 30px \" type=\"checkbox\" /></td>\r\n												<td colspan=\"2\" style=\"padding-left: 20px;\">I have already filed the document which is named above in Part B.</td>\r\n											</tr>\r\n										</tbody>\r\n									</table>\r\n									</td>\r\n								</tr>\r\n							</tbody>\r\n						</table>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n		<!-- PART D -->\r\n		<tr>\r\n			<td style=\" padding: 0 0 30px 0;\">\r\n			<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n				<tbody>\r\n					<tr>\r\n						<td style=\"background-color: #000; color: #fff; padding: 10px 20px; font-weight: bold; font-size: 20px; border: 2px solid #000;\"><span style=\"margin-right: 20px;\">PART D </span>INTERSTATE SERVICE</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"border: 2px solid #000; padding: 15px;\">\r\n						<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n							<tbody>\r\n								<tr>\r\n									<td style=\"padding-bottom: 15px;\">This part only applies if you served the document interstate. Tick as applicable.</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"padding-bottom: 15px;\">\r\n									<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n										<tbody>\r\n											<tr>\r\n												<td style=\"height: 30px; width: 30px; min-width: 30px; \"><input name=\"check5\" style=\"margin: 0; vertical-align: top; height: 30px; width: 30px \" type=\"checkbox\" /></td>\r\n												<td colspan=\"2\" style=\"padding-left: 20px;\">I did attach the notice under the <i>Service and Execution of Process Act 1992</i> (Commonwealth) to the document.</td>\r\n											</tr>\r\n										</tbody>\r\n									</table>\r\n									</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"padding-bottom: 15px;\">\r\n									<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n										<tbody>\r\n											<tr>\r\n												<td style=\"height: 30px; width: 30px; min-width: 30px; \"><input name=\"check5\" style=\"margin: 0; vertical-align: top; height: 30px; width: 30px \" type=\"checkbox\" /></td>\r\n												<td colspan=\"2\" style=\"padding-left: 20px;\">I did not attach the notice under the <i>Service and Execution of Process Act 1992</i> (Commonwealth) to the document.</td>\r\n											</tr>\r\n										</tbody>\r\n									</table>\r\n									</td>\r\n								</tr>\r\n							</tbody>\r\n						</table>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n		<!-- Warning -->\r\n		<tr>\r\n			<td style=\" padding: 0 0 30px 0;\">\r\n			<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n				<tbody>\r\n					<tr>\r\n						<td style=\"background-color: #000; color: #fff; padding: 10px 20px; font-weight: bold; font-size: 20px; border: 2px solid #000;\"><span style=\"margin-right: 20px;\">Warning </span></td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"border: 2px solid #000; padding: 15px;\">\r\n						<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n							<tbody>\r\n								<tr>\r\n									<td style=\"padding-bottom: 15px;\">Section 216 of the Queensland Civil and Administrative Tribunal Act 2009 makes it an offence for a person to knowingly give the registry documents containing false or misleading information. Maximum penalty for such an offence – 100 penalty units.</td>\r\n								</tr>\r\n							</tbody>\r\n						</table>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n		<!-- SIGNATURE -->\r\n		<tr>\r\n			<td style=\" padding: 0 0 30px 0;\">\r\n			<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n				<tbody>\r\n					<tr>\r\n						<td style=\"background-color: #000; color: #fff; padding: 10px 20px; font-weight: bold; font-size: 20px; border: 2px solid #000;\"><span style=\"margin-right: 20px;\">SIGNATURE </span></td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"border: 2px solid #000; padding: 15px;\">\r\n						<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n							<tbody>\r\n								<tr>\r\n									<td><b>Sworn</b> (or <b>affirmed</b>) by <i>(insert full name)</i></td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"height: 25px; padding:0 15px; width: 100%; border: 2px solid #000;\">&nbsp;</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"padding: 15px 0;\">\r\n									<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n										<tbody>\r\n											<tr>\r\n												<td style=\"padding-right: 5px;\">on</td>\r\n												<td style=\"height: 25px; padding:0 15px; width: 50%; border: 2px solid #000;\">&nbsp;</td>\r\n												<td style=\"padding-left: 5px;\">at</td>\r\n												<td style=\"padding-right: 5px;\"><i>(place)</i></td>\r\n												<td style=\"height: 25px; padding:0 15px; width: 50%; border: 2px solid #000;\">&nbsp;</td>\r\n											</tr>\r\n										</tbody>\r\n									</table>\r\n									</td>\r\n								</tr>\r\n								<tr>\r\n									<td>in the presence of:</td>\r\n								</tr>\r\n								<tr>\r\n									<td>\r\n									<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n										<tbody>\r\n											<tr>\r\n												<td style=\"width: 50%; padding: 0 10px 0 0;\">&nbsp;</td>\r\n												<td style=\"width: 50%; padding: 0 0 0 10px;\">&nbsp;</td>\r\n											</tr>\r\n											<tr>\r\n												<td style=\"padding:5px 20px 20px;\"><i>Person making affidavit to sign</i></td>\r\n												<td style=\"padding: 5px 20px 20px;\"><i>Person taking the affidavit to sign (qualified witness)</i></td>\r\n											</tr>\r\n											<tr>\r\n												<td style=\"width: 50%; padding: 0 10px 0 0;\">&nbsp;</td>\r\n												<td style=\"width: 50%; padding: 0 0 0 10px;\">&nbsp;</td>\r\n											</tr>\r\n											<tr>\r\n												<td style=\"padding: 0 20px;\">&nbsp;</td>\r\n												<td style=\"padding: 0 20px;\"><i>Print name</i></td>\r\n											</tr>\r\n											<tr>\r\n												<td style=\"padding: 0 20px;\">&nbsp;</td>\r\n												<td style=\"padding: 40px 0 0 20px;\"><b>Commissioner for declarations / solicitor / justice of the peace</b></td>\r\n											</tr>\r\n										</tbody>\r\n									</table>\r\n									</td>\r\n								</tr>\r\n							</tbody>\r\n						</table>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n		<!-- Instructions for completing -->\r\n		<tr>\r\n			<td style=\"padding-bottom: 20px;\">\r\n			<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n				<tbody>\r\n					<tr>\r\n						<td style=\"font-size: 20px;\"><b>Instructions for completing</b></td>\r\n					</tr>\r\n					<tr>\r\n						<td>\r\n						<h2>Affidavit of service</h2>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"padding: 15px; border: 2px solid #000;\">\r\n						<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n							<tbody>\r\n								<tr>\r\n									<td style=\"padding-bottom: 15px;\"><b>Use this form where you are seeking, or are required, to prove that you have provided a copy of a document to another party.</b></td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"padding-bottom: 0;\"><b>Default decisions</b>\r\n									<p style=\"margin-top: 0;\">Where you are applying for a decision in default of a response by a respondent you will need to prove that you have provided a copy of your application to the respondent. You may complete this affidavit, or in some cases you may complete the affidavit in the application for decision by default (for example the <i> Form 6 – application for decision by default – minor debt)</i>.</p>\r\n									</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"padding-bottom: 0;\"><b>Interstate service</b>\r\n									<p style=\"margin-top: 0;\">If the respondent resides in another state or territory you will need to provide an additional notice to the respondent, as required by the Service and Execution of Process Act 1992 (see also Practice Direction 2 of 2014). The notice is available on the QCAT website at www.qcat.qld.gov.au..</p>\r\n									</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"padding-bottom: 0;\"><b>Where to lodge your Affidavit of service</b>\r\n									<p style=\"margin-top: 0;\">The Affidavit of service must be lodged in the QCAT registry where the application that started the proceeding was lodged.</p>\r\n									</td>\r\n								</tr>\r\n								<tr>\r\n									<td>\r\n									<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n										<tbody>\r\n											<tr>\r\n												<td style=\"width: 100px; vertical-align: top;\"><i>By post:</i></td>\r\n												<td style=\"padding-bottom: 10px; vertical-align: top;\">\r\n												<p style=\"margin-top: 0;&gt;QCAT, GPO Box 1639, Brisbane QLD 4001&lt;/p&gt;\r\n                          &lt;p style=\"><i>If you are posting your original response and/or counter-application and copies to QCAT, you need to include a stamped self-addressed A4 envelope with your material.</i></p>\r\n												</td>\r\n											</tr>\r\n											<tr>\r\n												<td style=\"width: 100px; vertical-align: top;\"><i>In person:</i></td>\r\n												<td style=\"vertical-align: top;\">\r\n												<p style=\"margin-top: 0;\">QCAT, Level 9, Bank of Queensland Building, 259 Queen Street, Brisbane QLD 4000, or at any Magistrates Court outside of the Brisbane CBD.</p>\r\n												</td>\r\n											</tr>\r\n										</tbody>\r\n									</table>\r\n									</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"padding: 0;\">\r\n									<p>For more information visit www.qcat.qld.gov.au or call 1300 753 228.</p>\r\n									</td>\r\n								</tr>\r\n								<tr>\r\n									<td><b>PART B DETAILS OF SERVICE</b>\r\n									<p>Refer to the Queensland Civil and Administrative Tribunal Rules 2009 and the tribunal’s practice directions for service requirements available at www.qcat.qld.gov.au.</p>\r\n\r\n									<p>Insert your full name and residential or business address or place of employment.</p>\r\n\r\n									<p>If the entity served is not an individual then the correct name must be used. For example, a company name, business name (regardless of whether it is registered) or a State agency name. For further information you can refer to the tribunal’s factsheet How to identify and name parties in QCAT available at www.qcat.qld.gov.au.</p>\r\n\r\n									<p>If you are serving an application for a minor debt claim you must deliver the copy to an entity personally and in a way that complies with QCAT’s practice direction on service. Practice Directions are available at www.qcat.qld.gov.au.</p>\r\n									</td>\r\n								</tr>\r\n							</tbody>\r\n						</table>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n		<!-- Instructions for completing -->\r\n		<tr>\r\n			<td style=\"padding: 15px; border: 2px solid #000;\">\r\n			<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n				<tbody>\r\n					<tr>\r\n						<td><b>SIGNATURE</b>\r\n						<p>Please sign in the presence of a person who is authorised by the Oaths Act 1867 to take an affidavit:</p>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td>\r\n						<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n							<tbody>\r\n								<tr>\r\n									<td style=\"padding-right: 20px; padding-bottom: 5px; vertical-align: top;\">(a)</td>\r\n									<td>a justice, commissioner for declarations or notary public under the law of Queensland, the Commonwealth or another State,</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"padding-right: 20px; padding-bottom: 5px; vertical-align: top;\">(b)</td>\r\n									<td>a lawyer,</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"padding-right: 20px; padding-bottom: 5px; vertical-align: top;\">(c)</td>\r\n									<td>a conveyancer, or another person authorised to administer an oath, under the law of the state, the Commonwealth or another state,</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"padding-right: 20px; padding-bottom: 5px; vertical-align: top;\">(d)</td>\r\n									<td>if the affidavit is taken outside Australia — a person authorised to administer an oath under the law of the place in which the affidavit is taken.</td>\r\n								</tr>\r\n							</tbody>\r\n						</table>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td><b>Each page must be signed in the presence of a qualified witness.</b>\r\n						<p>A qualified witness includes a lawyer, Justice of the Peace or a Commissioner for Declarations.</p>\r\n						<b>Your Information</b>\r\n\r\n						<p>QCAT collects your contact details for the purposes of compliance with the Queensland Civil and Administrative Tribunal Act 2009 in relation to proceedings in QCAT. QCAT may contact you to seek your assistance in research to assist in the evaluation of the operation of QCAT. You are not obliged to participate in feedback or surveys. If you do participate no identifying particulars will be published. QCAT will not disclose your contact details or any other personal information to a third party unless required by law.</p>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n		<!-- Footer start here -->\r\n		<tr>\r\n			<td style=\"padding-top: 30px;\"><img alt=\"qcat-footer\" data-align=\"center\" data-entity-type=\"file\" data-entity-uuid=\"6523ec8e-dffa-4d96-968b-b69a3a600d70\" src=\"/sites/default/files/inline-images/qcat-footer.png\" width=\"725\" /></td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n','','full_html'),('library',0,267,394,'en',0,'<table align=\"center\" style=\"width: 100%; max-width: 700px; margin: 0 auto; border-collapse: collapse; border-spacing: 0; font-family: arial; font-size: 16px; padding: 0;\">\r\n	<tbody>\r\n		<tr>\r\n			<td><img alt=\"headermain\" data-align=\"center\" data-entity-type=\"file\" data-entity-uuid=\"4dbdc085-98be-4014-92ec-2725ada3021a\" src=\"/sites/default/files/inline-images/header.png\" width=\"725\" /></td>\r\n		</tr>\r\n		<tr>\r\n			<td>Form Number 9 (version 3)<br />\r\n			<i>Queensland Civil and Administrative Tribunal Rules 2009</i> (Rule 42)</td>\r\n		</tr>\r\n		<!-- Affidavit of service -->\r\n		<tr>\r\n			<td>\r\n			<h2>Affidavit of service</h2>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"padding-bottom: 30px;\">\r\n			<table align=\"center\" style=\"width: 100%; margin: 0 auto; border-collapse: collapse; border-spacing: \">\r\n				<tbody>\r\n					<tr>\r\n						<td style=\"width: 55%; padding-right: 30px;  vertical-align: top;\">\r\n						<p><i>Refer to attached instructions prior to filling out this form.</i></p>\r\n						<span style=\"padding: 15px; border: 2px solid black; background-color: #ccc; display: block;\">Please note that this is an affidavit. Each of the following pages must be signed by the person making the affidavit in the presence of a qualified witness (the person taking the affidavit).</span></td>\r\n						<td style=\"width: 45%; padding: 0; vertical-align: top;\">\r\n						<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n							<tbody>\r\n								<tr>\r\n									<td colspan=\"2\" style=\"padding: 10px; border: 2px solid black; background-color: #000; color: #FFF; font-weight: bold;\">For office use only</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"background-color: #CCC; border: 2px solid black; padding: 5px; width: 50%;\">Case number:</td>\r\n									<td style=\"background-color: #CCC; border: 2px solid black; padding: 5px; width: 50%;\">&nbsp;</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"background-color: #CCC; border: 2px solid black; padding: 5px; width: 50%;\">Date:</td>\r\n									<td style=\"background-color: #CCC; border: 2px solid black; padding: 5px; width: 50%;\">&nbsp;</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"background-color: #CCC; border: 2px solid black; padding: 5px; width: 50%;\">Registry:</td>\r\n									<td style=\"background-color: #CCC; border: 2px solid black; padding: 5px; width: 50%;\">&nbsp;</td>\r\n								</tr>\r\n							</tbody>\r\n						</table>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n		<!-- PART A -->\r\n		<tr>\r\n			<td style=\"padding: 0 0 30px 0;\">\r\n			<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n				<tbody>\r\n					<tr>\r\n						<td style=\"background-color: #000; color: #fff; padding: 10px 20px; font-weight: bold; font-size: 20px; border: 2px solid #000;\"><span style=\"margin-right: 20px;\">PART A </span>APPLICANT’S AND RESPONDENT’S DETAILS</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"padding: 15px; border: 2px solid #000;\">\r\n						<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n							<tbody>\r\n								<tr>\r\n									<td style=\"padding-bottom: 5px;\"><b>Case number</b> <i>(if known):</i></td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"height: 25px; padding:0 15px; width: 100%; border: 2px solid #000;\">&nbsp;</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"padding-top: 15px; font-weight: bold; padding-bottom: 5px;\">Applicant</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"height: 25px; padding:0 15px; width: 100%; border: 2px solid #000;\">&nbsp;</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"padding-top: 15px; font-weight: bold; padding-bottom: 5px;\">Respondent</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"height: 25px; padding:0 15px; width: 100%; border: 2px solid #000;\">&nbsp;</td>\r\n								</tr>\r\n							</tbody>\r\n						</table>\r\n						</td>\r\n					</tr>\r\n				</tbody>\r\n			</table>\r\n			</td>\r\n		</tr>\r\n		<!-- PART B -->\r\n		<tr>\r\n			<td style=\"padding: 0 0 30px 0;\">\r\n			<table align=\"center\" style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n				<tbody>\r\n					<tr>\r\n						<td style=\"background-color: #000; color: #fff; padding: 10px 20px; font-weight: bold; font-size: 20px; border: 2px solid #000;\"><span style=\"margin-right: 20px;\">PART B </span>DETAILS OF SERVICE</td>\r\n					</tr>\r\n					<tr>\r\n						<td style=\"padding: 15px; border: 2px solid #000;\">\r\n						<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n							<tbody>\r\n								<tr>\r\n									<td style=\"padding-bottom: 15px;\">\r\n									<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n										<tbody>\r\n											<tr>\r\n												<td style=\"padding-bottom: 5px; padding-right: 10px;\">I,</td>\r\n												<td style=\"height: 25px; padding:0 15px; width: 100%; border: 2px solid #000;\">&nbsp;</td>\r\n											</tr>\r\n											<tr>\r\n												<td style=\"padding-bottom: 5px; padding-right: 10px;\">&nbsp;</td>\r\n												<td style=\"width: 100%; padding-top: 5px;\"><i>(insert full name of person making affidavit)</i></td>\r\n											</tr>\r\n										</tbody>\r\n									</table>\r\n									</td>\r\n								</tr>\r\n								<tr>\r\n									<td>\r\n									<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n										<tbody>\r\n											<tr>\r\n												<td colspan=\"3\" style=\"padding-bottom: 5px; padding-right: 10px;\">of (insert residential or business address, or place of employment)</td>\r\n											</tr>\r\n											<tr>\r\n												<td colspan=\"3\" style=\"height: 25px; padding:0 15px; width: 100%; border: 2px solid #000;\">&nbsp;</td>\r\n											</tr>\r\n											<tr style=\"border-bottom: border: 2px solid #000;\">\r\n												<td style=\"height: 25px; padding:0 15px; width: 100%; border: 2px solid #000;\">&nbsp;</td>\r\n												<td style=\"padding: 0 20px; font-weight: bold;\">Postcode</td>\r\n												<td style=\"height: 25px; padding:0 15px; min-width: 100px; width: 100%; border: 2px solid #000;\">&nbsp;</td>\r\n											</tr>\r\n										</tbody>\r\n									</table>\r\n									</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"padding-bottom: 15px;\">state on oath / solemnly and sincerely affirm and declare:</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"padding-bottom: 15px;\">\r\n									<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n										<tbody>\r\n											<tr>\r\n												<td style=\"width: 80px; min-width: 80px;\">On the</td>\r\n												<td style=\"height: 25px; padding:0 15px; width: 200px; border: 2px solid #000; max-width: 200px;\">&nbsp;</td>\r\n												<td style=\"padding: 0 20px;\">at</td>\r\n												<td style=\"height: 25px; padding:0 15px; width: 150px; border: 2px solid #000; min-width: 150px;\">&nbsp;</td>\r\n												<td style=\"padding: 0 20px; white-space: nowrap;\">am / pm,</td>\r\n											</tr>\r\n										</tbody>\r\n									</table>\r\n									</td>\r\n								</tr>\r\n								<tr>\r\n									<td style=\"padding-bottom: 15px;\">\r\n									<table style=\"border-collapse: collapse; border-spacing: 0; width: 100%;\">\r\n										<tbody>\r\n											<tr>\r\n												<td style=\"width: 80px; min-width: 80px;\">I served</td>\r\n												<td style=\"height: 25px; padding:0 15px; border: 2px solid #000;\">&nbsp;</td>\r\n											</tr>\r\n											<tr>\r\n												<td style=\"width: 8