INSERT INTO `paragraph__field_notes` VALUES ('attendance_note',0,1086,1835,'en',0,'No response'),('attendance_note',0,1087,1836,'en',0,'No response. No response neighbours'),('attendance_note',0,1088,1837,'en',0,'No response. No response neighbours'),('attendance_note',0,1090,1839,'en',0,'Female (60-70 yrs, short blonde hair, medium build, accent) answered door and identified herself as subject.'),('attendance_note',0,1166,1915,'en',0,'Property found padlock gated. Appears unoccupied.'),('attendance_note',0,1167,1916,'en',0,'Property still padlock gated with no changes. Still appears unoccupied. Docs letterboxed '),('attendance_note',0,1168,1917,'en',0,'No response. Enquiries revealed mobile number for Lorenzo of 0488 093 233 but no response from the number'),('attendance_note',0,1169,1918,'en',0,'No response. Spoke to Lorenzo on mobile - he stated that he is still residing at the given address but works night shifts at the moment and should be available tomorrow or Friday before 2:00pm'),('attendance_note',0,1170,1919,'en',0,'See notes re: Lorenzo Cazzola.\r\nEnquiries have suggested that Veronica may have another residential address in Mackay area where she stays whilst Lorenzo works shifts.'),('attendance_note',0,1171,1920,'en',0,'No response. Adjacent female neighbour unable to confirm ID of occupants of given address'),('attendance_note',0,1172,1921,'en',0,'No response. No accumulation of post in letterbox. No vehicles outside'),('attendance_note',0,1190,1939,'en',0,'Per male adult occupant, subject resides at given address but not present. Refused further info except she works weekdays until 6:00pm usually.'),('attendance_note',0,1199,1948,'en',0,'No response from intercom of unit 20 and no response from knocking at the front door, access gained via Cronin Street. No response immediate neighbours.'),('attendance_note',0,1200,1949,'en',0,'No response from intercom of unit 20 and no response from knocking at the front door, access gained via Cronin Street. Enquiries made with Yardsman Brian for the building who stated that an inspection of the unit may have occurred that day. He had no knowledge of the Subject and no knowledge of current occupants of unit 20. Enquiries made with tenants in unit 16, directly below unit 20, who stated they have not heard any noise amanating from the unit in over one week.'),('attendance_note',0,1201,1950,'en',0,'Met with current female adtult occupant who stated that she rents the property and has no knowledge of the Subject other than observing mail delivered to the property in his name. She stated she has rented for approximately 18 months but failed to provide the name of the managing agents. Seemed genuine. Enquiries with neighbouring residents provided no additional information as to the Subject.'),('attendance_note',0,1202,1951,'en',0,'Same result as above.'),('attendance_note',0,1203,1952,'en',0,'Employees at the property confirmed that the Subject was present but, upon requesting that he come to accept, they spoke to him but returned stating that he was \"not available\" to accept service. They were clearly assisting him to evade service. In the circumstances, a copy of the documents were in fact left with Jordan Barnett (Admin Officer) at such time who stated that he would take them through to the Subject.\r\nNote that Debt Options is now located on Ground Floor of 9 Bay Street.'),('attendance_note',0,1204,1953,'en',0,'No response from intercom. No response from intercom for Units 19 and 21.'),('attendance_note',0,1205,1954,'en',0,'No response from intercom. No response from intercom for Units 19 and 21.'),('attendance_note',0,1206,1955,'en',0,'No response from intercom and no lights observed in the property, the unit having been indicated by the yardsman previously. No response from intercom for Units 19 and 21.'),('attendance_note',0,1207,1956,'en',0,'No response from knocking at front door. No response neighbours. New build property.'),('attendance_note',0,1208,1957,'en',0,'No response from knocking at front door.  Opposite neighbour recognised Subject\'s surname at given address but had no further info.'),('attendance_note',0,1209,1958,'en',0,'No response from knocking at front door. No response from immediate neighbours.'),('attendance_note',0,1210,1959,'en',0,'No response from knocking at front door. '),('attendance_note',0,1211,1960,'en',0,'SEE ALL ATTENDANCE NOTES FOR JOB NO. 932712 - same address and surname.'),('attendance_note',0,1219,1968,'en',0,'No response from repeated knocking.'),('attendance_note',0,1220,1969,'en',0,'Female receptionist stated that Subject is not present and to try back later in the week.'),('attendance_note',0,1221,1970,'en',0,'Female receptionist stated Subject again not present and refused to discuss any further information or provide contact number for Subject.'),('attendance_note',0,1222,1971,'en',0,'Female receptionist stated that Subject no longer works for the business. Refused to provide contact number for Subject and stated we should speak to \"Craig\" to see if any details could be provided.'),('attendance_note',0,1224,1973,'en',0,'Property is large gated property on acreage with guard dog. Gates locked and no response to honking horn.'),('attendance_note',0,1225,1974,'en',0,'Property is large gated property on acreage with guard dog. Gates locked and no response to honking horn. Internet searches show possible telephone number for Subject at address of 03 8339 4933 but no response from same.'),('attendance_note',0,1246,1995,'en',0,'No response from property or adjacent neighbours.'),('attendance_note',0,1247,1996,'en',0,'No response from property or adjacent neighbours.'),('attendance_note',0,1248,1997,'en',0,'No response from property or adjacent neighbours.'),('attendance_note',0,1249,1998,'en',0,'No response from property or adjacent neighbours. Further enquiries made revealed a mobile number for the Subject of 0481 333 480. Upon contacting the same, a male identified himself as the Subject and stated that he currently resides in Victoria at 42 Poolman Street, Port Melbourne VIC 3207.\r\nA copy of the documents were left in the letterbox for the given address at such time.'),('attendance_note',0,1374,2123,'en',0,'Found def at work address'),('attendance_note',0,1382,2131,'en',0,'also served by letterbox at residential'),('attendance_note',0,1481,2230,'en',0,'Ffregregerg'),('attendance_note',0,1583,2332,'en',0,'fsdfsdfsfd'),('attendance_note',0,1584,2333,'en',0,'aasdads'),('attendance_note',0,1585,2334,'en',0,'asdasd'),('attendance_note',0,1586,2335,'en',0,'dfdfsdfsdf'),('attendance_note',0,1588,2337,'en',0,'asdasd'),('attendance_note',0,1589,2338,'en',0,'asdasd'),('attendance_note',0,1590,2339,'en',0,'dsdf'),('attendance_note',0,1634,2383,'en',0,'Neighbour said def not home'),('attendance_note',0,1635,2384,'en',0,'No response from anyone anywhere');
