INSERT INTO `search_dataset` VALUES (3,'en','node_search',' associated process servers associated process servers admin sat 23062018 724  ',0),(167,'en','node_search',' statement of claim statement of claim douglas o connor sat 25052019 1515  ',0),(168,'en','node_search',' affidavit of affidavit of douglas o connor sat 25052019 1516  ',0),(197,'en','node_search',' application for divorce application for divorce douglas o connor mon 7102019 1243  ',0),(219,'en','node_search',' notice of motion notice of motion 28 day s douglas o connor sun 10112019 1235  ',0),(245,'en','node_search',' application for minor civil dispute application for minor civil dispute 5 day s admin mon 20042020 2122  ',0),(248,'en','node_search',' subpoena to attend subpoena to attend 5 day s admin mon 20042020 2150  ',0),(250,'en','node_search',' subpoena to produce criminal subpoena to produce criminal 5 day s admin mon 20042020 2341  ',0),(258,'en','node_search',' nsw environment protection authority nsw environment protection authority admin thu 23072020 2312 543231 off  ',0),(260,'en','node_search',' notice to show cause notice to show cause admin thu 23072020 2315  ',0),(261,'en','node_search',' ucpa affidavit 2016 completed ucpa affidavit 2016 completed admin thu 23072020 2338 form 41 version 2 ucpr 358 affidavit of service of douglas o connor sworn 29 september 2017 court details court node fieldcourt division node fielddivision list node fieldlist registry node fieldregistry case number node fieldcaseno title of proceedings first plaintiff node fieldparties fieldname number of plaintiffs 1 first defendant node fieldparty2 fieldname number of defendants 1 filing details filed for node fieldparties fieldfullname node fieldparties fieldpartytype legal representative node fieldclient node fieldclient fieldclientaddress legal representative reference node fieldclientref contact name and telephone node fieldclient fieldtelephone affidavit details name douglas o connor address level 25 aurora place 88 phillip street sydney nsw 2000 occupation licensed process server date i say on oath 1 i am over the age of 16 years 2 on node fielddateservice i served node fieldnametoservervalue with the following documents a node fielddocuments fielddocument node fielddocuments fieldname node fielddocuments fieldamount node fielddocuments fielduntitled node fielddocuments fielddate 3 i served the documents by node fieldmethodofservice node fieldpersondeliveredto a person apparently over the age of 16 years and apparently a resident employee at the property at node fieldparaaddress 4 at the said time and place of service i had a conversation with the person so served by me in words to the following effect i said are you able to accept service of these documents on behalf of node fieldnametoservervalue as referred to therein the person replied yes i am sworn on at signature of deponent name of witness address of witness capacity of witness and as a witness i certify the following matters concerning the person who made this affidavit the deponent 1 i saw the face of the deponent 2 i have confirmed the deponent s identity using the following identification document current driver licence signature of witness affidavit  ',0),(262,'en','node_search',' federal court general affidavit of service federal court general affidavit of service admin thu 23072020 2340 form 59 rule 29021 affidavit of service of douglas o connor no sad 133 of 2018 federal court of australia district registry south australia division civil acn 153 364 491 ltd in liquidation plaintiff gp no1 pty ltd in liquidation first defendant gavin moss second defendant affidavit of douglas o connor address level 25 88 phillip street sydney nsw 2000 occupation licensed process server date i douglas o connor of level 25 88 phillip street sydney nsw 2000 licensed process server say on oath i am over the age of 16 years on friday the 15th june 2018 at 158pm at suite 1903 level 19 31 market street sydney nsw 2000 i served the first defendant with the following documents a originating process filed on 12 june 2018 b affidavit of robert allan jacobs filed on 12 june 2018 filed on behalf of name role of party quaker chemical australasia pty ltd prepared by name of person lawyer douglas o connor process server law firm if applicable silberstein associates tel 2 8075 4699 fax email rob silbersteinnetau address for service include state and postcode level 36 gateway tower 1 macquarie place sydney nsw 2000 version 2 form approved 9052013 3 i served the documents by handing the same personally to gavin moss at suite 1903 level 19 31 market street sydney nsw 2000 such address being the registered office of the said first defendant 4 at the said time and place of service i had a conversation with the person so served by me in words to the following effect i said are you able to accept service on behalf of gp no1 pty ltd in liquidation as referred to in these documents he replied yes i am gavin moss sworn by the deponent at belrose in nsw on before me signature of deponent signature of witness name and qualification of witness instructions for completing affidavits these instructions do not form part of the affidavit and must be deleted before the affidavit is sworn or affirmed each page of the affidavit but not any annexure must be signed by the deponent other than a deponent who is unable to sign because of a physical disability and the person before whom it is sworn r29027 an affidavit must be made in the first person r 29021 an affidavit must be divided into numbered paragraphs each dealing with a separate subject to the extent practicable r29023 if facts in the affidavit are supported by a document annex a copy of the document to the affidavit unless the document is an original or is of such dimensions that it cannot be annexed r29024 in which case it must be exhibited r29025 each page of the affidavit including any annexure must be consecutively numbered starting with page 1 r29026 attach a certificate to the first page of each annexure and exhibit the certificate must be entitled in the same manner as the affidavit and identified by the deponent s initials followed by a number starting with 1 r29028 for example the first annexure of an affidavit of james william green would be identified as jwg1 the second annexure would be jwg2 and the first exhibit to that affidavit would be jwg3 no subsequent annexure or exhibit in any later affidavit sworn by the same deponent may duplicate the number of a previous annexure or exhibit r290210 each exhibit to an affidavit must be signed on the first page of the exhibit by the person before whom the affidavit is sworn r290211 the deponent must swear or affirm the affidavit before a person authorised by law to witness the swearing of affidavits witness persons authorised to witness an affidavit in federal court proceedings are a judge of the court the registrar a deputy registrar a district registrar a deputy district registrar authorised under s 44 of the federal court of australia act a member of staff of the federal court authorised under s 44 of the federal court of australia act a justice of the peace a commissioner for affidavits a commissioner for declarations any other person who is authorised to administer oaths for the purposes of the federal court or the high court or the supreme court of a state or territory includes lawyer with a current practising certificate serve copies of all documents exhibited or annexed to an affidavit with the affidavit r2905 if the deponent is illiterate see rules 29041 5 if the deponent is blind see rules 29042 3 5 if the deponent is incapable of signing the affidavit because of a physical disability see rules 29044 5 affidavit  ',0),(263,'en','node_search',' workers compensation certificate of service form workers compensation certificate of service form admin thu 23072020 2341 july 2011 matter no 20 office use only certificate certificate of service this is the approved fo