DROP TABLE IF EXISTS `xero_client_contacts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `xero_client_contacts` (
  `nid` int unsigned NOT NULL COMMENT 'Drupal Client node ID.',
  `xero_contact_id` varchar(64) NOT NULL COMMENT 'Xero ContactID GUID.',
  `synced_at` int NOT NULL COMMENT 'Last successful sync unix timestamp.',
  PRIMARY KEY (`nid`),
  KEY `xero_contact_id` (`xero_contact_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Maps Drupal Client node IDs to Xero ContactIDs.';
/*!40101 SET character_set_client = @saved_cs_client */;

